"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8694],{60274:e=>{e.exports=JSON.parse('{"functions":[{"name":"findSlateVariant","desc":"Finds the slate `MaterialVariant`, if the material pack is installed.","params":[],"returns":[{"desc":"Nil when the pack is absent; walls fall back to plain slate.","lua_type":"Instance?"}],"function_type":"static","private":true,"source":{"line":37,"path":"src/main/server/bootstrap.luau"}},{"name":"createBuildAssets","desc":"Resolves the prefab source, creates the maze folder and the wall template,\\nand strips per-part overhead off every source prefab.","params":[],"returns":[{"desc":"","lua_type":"BuildAssets"}],"function_type":"static","private":true,"source":{"line":51,"path":"src/main/server/bootstrap.luau"}},{"name":"bootstrap","desc":"Writes every maze singleton. Call once, before `startup`.","params":[],"returns":[],"function_type":"static","source":{"line":75,"path":"src/main/server/bootstrap.luau"}}],"properties":[],"types":[],"name":"bootstrap","desc":"Builds every maze singleton and shared asset, once, before any system runs.\\n\\nThis work used to happen at module load, scattered across `budget`, `seed`,\\n`registry`, `builder` and `observers`. Requiring a file now does nothing, and\\nthe whole startup sequence is one readable list in one place.\\n\\nIt is called explicitly by the server entry point rather than being a system,\\nbecause system registration order is not guaranteed: as a system it ticked\\n*after* `unload` and `demolish` on the first frame and they read singletons\\nthat did not exist yet. The entry script is the one place that can promise\\nordering, so ordering lives there.","tags":["core"],"realm":["Server"],"source":{"line":18,"path":"src/main/server/bootstrap.luau"}}')}}]);